require_once __DIR__.'/bootstrap.php';require QA_ROOT.'/config/database.php';require __DIR__.'/support/account_tables.php';ini_set('error_log',QA_CASE_DIR.'/expected-rollback.log');
require QA_ROOT.'/classes/examinations/ExamBooking.php';require QA_ROOT.'/classes/scheduling/AppointmentHeartbeat.php';
$db=(new Database)->getConnection();foreach(['users','student_profiles','notifications','email_outbox','system_logs','system_settings','schedules','holidays','school_closures','counseling_appointments','counseling_forms','entrance_exam_appointments','entrance_exam_daily_limits'] as $table)accountTemporaryTable($db,$table);
foreach(['rescheduled_from_id'=>'INT NULL','rescheduled_to_id'=>'INT NULL','reschedule_pending'=>'TINYINT(1) NOT NULL DEFAULT 0'] as $name=>$type){$q=$db->prepare('SHOW COLUMNS FROM entrance_exam_appointments LIKE ?');$q->execute([$name]);if(!$q->fetch())$db->exec('ALTER TABLE entrance_exam_appointments ADD COLUMN '.$name.' '.$type);}
$checks=[];function ok($n,$v){global $checks;if(!$v)throw new RuntimeException($n);$checks[]=$n;}function denied($n,$fn){$err=null;try{$fn();}catch(Throwable $e){$err=$e;}ok($n,(bool)$err);}
$db->exec("INSERT INTO system_settings(setting_key,setting_value) VALUES('entrance_exam_enabled','1');INSERT INTO users(id,role,email,first_name,last_name,grade_level_applying,is_active,archived) VALUES(99201,'examinee','one@example.invalid','Synthetic','One','1st Year College',1,0),(99202,'examinee','two@example.invalid','Synthetic','Two','Grade 11',1,0),(99203,'student','student@example.invalid','Synthetic','Student',NULL,1,0),(99204,'admin','admin@example.invalid','Synthetic','Admin',NULL,1,0)");
$date=(new DateTimeImmutable('tomorrow'))->modify('next Monday')->format('Y-m-d');$db->prepare("INSERT INTO schedules(id,title,event_type,start_datetime,end_datetime,is_active,created_by) VALUES(1,'Synthetic College Exam','entrance_exam',?,?,1,99204)")->execute([$date.' 08:00:00',$date.' 17:00:00']);$booking=new ExamBooking($db);$a=$booking->availability($date);
ok('Schedule remains visible without a daily limit',count($a['scheduled'])===1&&$a['status']==='available'&&count($a['slots'])===1);ok('Exact saved start/end hours are displayed',$a['scheduled'][0]['start_at']===$date.' 08:00:00'&&$a['scheduled'][0]['end_at']===$date.' 17:00:00');ok('Default booking has no attendee limit',$a['capacity']===null&&count($a['slots'])===1);
$db->prepare("INSERT INTO entrance_exam_daily_limits(date,max_appointments,exam_time,exam_end_time) VALUES(?,2,'09:00:00','10:00:00')")->execute([$date]);$a=$booking->availability($date);ok('Only the actual session is offered, without generated hourly slots',count($a['slots'])===1&&$a['slots'][0]['value']==='08:00:00');ok('Old time-window values do not override the scheduled session',$a['slots'][0]['end_at']===$date.' 17:00:00');ok('Daily places are calculated from configured capacity',$a['remaining']===2);
$db->prepare("INSERT INTO counseling_appointments(user_id,appointment_date,appointment_time,session_duration,status,concern_description) VALUES(99203,?,'08:00:00',60,'confirmed','PRIVATE_CONCERN_SENTINEL')")->execute([$date]);$db->prepare("INSERT INTO schedules(id,title,event_type,start_datetime,end_datetime,is_active,created_by) VALUES(2,'Synthetic counseling availability','counseling',?,?,1,99204)")->execute([$date.' 08:00:00',$date.' 12:00:00']);ok('Counseling bookings and availability can run alongside the exam',count($booking->slots($date))===1);
$db->prepare("INSERT INTO schedules(id,title,event_type,start_datetime,end_datetime,is_active,created_by) VALUES(3,'Other office event','event',?,?,1,99204)")->execute([$date.' 10:00:00',$date.' 11:00:00']);$a=$booking->availability($date);ok('Other blocked office activities retain conflict protection',$a['status']==='unavailable'&&!$a['slots']&&count($a['scheduled'])===1);$db->exec('DELETE FROM schedules WHERE id=3');
denied('Invented intermediate appointment time is rejected',fn()=>$booking->book(99201,$date,'09:00:00','Synthetic school',null,1));denied('Wrong scheduled event is rejected',fn()=>$booking->book(99201,$date,'08:00:00','Synthetic school',null,999));denied('A student cannot use examinee booking',fn()=>$booking->book(99203,$date,'08:00:00','Synthetic school',null,1));ok('Malformed date input fails safely',$booking->availability(['bad'])['status']==='invalid');ok('Same-day booking stays unavailable',!$booking->slots(date('Y-m-d')));
$db->prepare("INSERT INTO holidays(name,date,type,year) VALUES('Synthetic holiday',?,'regular',?)")->execute([$date,substr($date,0,4)]);$a=$booking->availability($date);ok('Holiday closes booking while leaving the exam visible',$a['closed']&&!$a['slots']&&count($a['scheduled'])===1);$db->exec('DELETE FROM holidays');$db->prepare("INSERT INTO school_closures(reason,start_date,end_date,created_by) VALUES('Synthetic closure',?,?,99204)")->execute([$date,$date]);ok('School closure blocks exact sessions',!$booking->slots($date));$db->exec('DELETE FROM school_closures');
$id=(int)$booking->book(99201,$date,'08:00:00','Synthetic school',null,1);$r=$db->query('SELECT * FROM entrance_exam_appointments WHERE id='.$id)->fetch(PDO::FETCH_ASSOC);ok('Booking saves the staff-scheduled start and end',$r['preferred_time']==='08:00:00'&&$r['slot_end_at']===$date.' 17:00:00');ok('Booking retains notification delivery',(int)$db->query("SELECT COUNT(*) FROM notifications WHERE user_id=99201 AND related_table='entrance_exam_appointments'")->fetchColumn()===1);denied('An existing active exam cannot be booked again',fn()=>$booking->book(99201,$date,'08:00:00','Synthetic school',null,1));
ok('A saved exam consumes one configured place',$booking->availability($date)['remaining']===1);ok('Availability never exposes counseling concerns',!str_contains(json_encode($booking->availability($date)),'PRIVATE_CONCERN_SENTINEL'));$booking->book(99202,$date,'08:00:00','Synthetic school',null,1);$a=$booking->availability($date);ok('Full date retains visible scheduled exams but closes booking',$a['status']==='full'&&count($a['scheduled'])===1&&!$a['slots']);
$clock=new DateTimeImmutable($date.' 10:00:00',new DateTimeZone('Asia/Manila'));$heartbeat=new AppointmentHeartbeat($db,static function()use(&$clock){return $clock;});$heartbeat->setLogging(false);ok('Exam is not missed after the old two-hour duration',$heartbeat->run(true)['exam_missed']===0);$clock=$clock->setTime(17,0);ok('Missed deadline follows the stored scheduled end',$heartbeat->run(true)['exam_missed']===2);
$db->exec("UPDATE entrance_exam_appointments SET status='cancelled'");ok('Cancelled bookings release capacity',$booking->availability($date)['remaining']===2);$db->exec("UPDATE system_settings SET setting_value='0' WHERE setting_key='entrance_exam_enabled'");$a=$booking->availability($date);ok('Disabled booking does not hide the event',$a['status']==='disabled'&&count($a['scheduled'])===1&&!$a['slots']);
$db->exec("UPDATE system_settings SET setting_value='1' WHERE setting_key='entrance_exam_enabled';DELETE FROM entrance_exam_appointments");$db->prepare("UPDATE entrance_exam_daily_limits SET max_appointments=0 WHERE date=?")->execute([$date]);ok('Zero capacity cannot be booked',!$booking->slots($date));$db->prepare("UPDATE entrance_exam_daily_limits SET max_appointments=2 WHERE date=?")->execute([$date]);
$db->prepare("INSERT INTO schedules(id,title,event_type,start_datetime,end_datetime,is_active,created_by) VALUES(3,'Second synthetic session','entrance_exam',?,?,1,99204)")->execute([$date.' 08:00:00',$date.' 12:00:00']);ok('Multiple scheduled sessions are visible',count($booking->slots($date))===2);denied('Ambiguous time requires a specific session',fn()=>$booking->book(99201,$date,'08:00:00','Synthetic school'));$selected=(int)$booking->book(99201,$date,'08:00:00','Synthetic school',null,3);ok('Selected session determines its own end',$db->query('SELECT slot_end_at FROM entrance_exam_appointments WHERE id='.$selected)->fetchColumn()===$date.' 12:00:00');ok('A date without a published exam has a clear empty state',$booking->availability((new DateTimeImmutable($date))->modify('+1 day')->format('Y-m-d'))['status']==='no_exam');
